INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2021-s0-1', 'exam-calculus-2-2021', 'exam-calculus-2-2021-sec-0', 0, '极限().', '极限 $\\lim_{(x,y)\\to(0,0)}\\frac{x-y}{x+y}$ ( ).', '["等于 1","等于 -1","等于 0","不存在"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2021长沙理工大学高数A（二）期末', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2021-s0-2', 'exam-calculus-2-2021', 'exam-calculus-2-2021-sec-0', 0, '设D是由所确定的闭区域，则.', '设D是由 $x^{2}+y^{2}\\leq9,y\\geq0$ 所确定的闭区域，则 $\\iint_{D}\\sqrt{9-x^{2}-y^{2}}\\mathrm{d}x\\mathrm{d}y=(\\quad)$ .', '["$3\\\\pi$","$9\\\\pi$","$27\\\\pi$","$81\\\\pi$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2021长沙理工大学高数A（二）期末', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2021-s0-3', 'exam-calculus-2-2021', 'exam-calculus-2-2021-sec-0', 0, '设为，为在第一卦限的部分，则下', '设 $\\Sigma$ 为 $z = \\sqrt{2 - x^{2} - y^{2}}$ ， $\\Sigma_{1}$ 为 $\\Sigma$ 在第一卦限的部分，则下列等式正确的是（）.', '["$\\\\iint_{\\\\Sigma} x \\\\, dS = 4 \\\\iint_{\\\\Sigma_{1}} x \\\\, dS$","$\\\\iint_{\\\\Sigma} y \\\\, dS = 4 \\\\iint_{\\\\Sigma_{1}} x \\\\, dS$","$\\\\iint_{\\\\Sigma} z \\\\, dS = 4 \\\\iint_{\\\\Sigma_{1}} x \\\\, dS$","$\\\\iint_{\\\\Sigma} xyz \\\\, dS = 4 \\\\iint_{\\\\Sigma_{1}} xyz \\\\, dS$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2021长沙理工大学高数A（二）期末', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2021-s0-4', 'exam-calculus-2-2021', 'exam-calculus-2-2021-sec-0', 0, '设为曲线与所围面积，记，则.', '设 $a_{n}$ 为曲线 $y = x^{n}$ 与 $y = x^{n+1} (n = 1, 2 \\cdots)$ 所围面积，记 $S = \\sum_{n=1}^{\\infty} a_{n}$ ，则 $S = (\\quad)$ .', '["$\\\\frac{1}{2}$","$-\\\\frac{1}{2}$","1","-1"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2021长沙理工大学高数A（二）期末', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
