INSERT INTO public.exam_sections (id, exam_id, title, order_index) VALUES ('exam-calculus-2-2021-sec-3', 'exam-calculus-2-2021', '四、证明题', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, title = EXCLUDED.title, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2021-s3-0', 'exam-calculus-2-2021', 'exam-calculus-2-2021-sec-3', 4, '设在上连续，证明', '设 $f(x)$ 在 $[0, a]$ 上连续，证明：
